using System.Security.Claims;
using System.Text.Json.Nodes;
using Npgsql;
namespace TWM.API.Services;
public sealed class StateService(DatabaseService database,RelationalStore relational,AccountService accounts) {
 public static readonly HashSet<string> Shared=["catalog","orders","quotes","returns","users","companies","categories","geography","zones","messages","conversations"];
 public static readonly HashSet<string> Private=["cart","wishlist","selectedVendor","comuna","shippingMethod"];
 public static string Text(JsonNode? n,string key,string fallback="")=>n?[key]?.ToString()??fallback;
 public static decimal Number(JsonNode? n,string key,decimal fallback=0)=>decimal.TryParse(Text(n,key),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var v)?v:fallback;
 public static JsonArray Rows(JsonNode? n)=>n as JsonArray??new();
 public static string Id(JsonNode? n)=>Text(n,"id");
 public static bool Admin(ClaimsPrincipal u)=>u.IsInRole("Admin");
 public static bool Seller(ClaimsPrincipal u)=>Admin(u)||u.IsInRole("Vendedor");
 public static string Rut(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.NameIdentifier)??"guest";
 public static bool IsShared(string key)=>Shared.Contains(key)||key.StartsWith("reviews:")||key.StartsWith("questions:");
 public static string Owner(string key,string rut)=>IsShared(key)?"global":rut;
 public static string Key(string key,string rut)=>Owner(key,rut)+":"+key;
 public static JsonNode? Get(Dictionary<string,JsonNode?> data,string key,string rut="global")=>data.GetValueOrDefault(Key(key,rut));
 public static JsonArray List(Dictionary<string,JsonNode?> data,string key,string rut="global")=>Rows(Get(data,key,rut));
 public static bool Visible(string key,JsonNode? row,ClaimsPrincipal user)=>key switch{
  "catalog"=>Text(row,"estado")!="Borrador"||Admin(user)||Text(row,"ownerRut")==Rut(user),
  "orders" or "quotes" or "returns" or "messages" or "conversations"=>Admin(user)||Text(row,"customerRut")==Rut(user)||(Seller(user)&&Text(row,"sellerRut")==Rut(user)),
  "users"=>Admin(user),"companies"=>Admin(user)||Text(row,"ownerRut")==Rut(user),_=>true};
 public static decimal Price(JsonNode product,JsonNode? line=null){var variant=Rows(product["variantes"]).FirstOrDefault(v=>Text(v,"sku")==Text(line,"sku"));return Number(variant??product,variant==null?"precio":"price");}
 public async Task<Dictionary<string,JsonNode?>> Load(NpgsqlConnection c,NpgsqlTransaction? tx,CancellationToken ct){var data=new Dictionary<string,JsonNode?>();var stored=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('id',id,'payload',payload)::text FROM shopping_ui.documents",ct);foreach(var row in stored)data[Id(row)]=row?["payload"]?.DeepClone();await relational.Load(c,tx,data,ct);return data;}
 public async Task Save(NpgsqlConnection c,NpgsqlTransaction tx,string key,string rut,JsonNode? value,CancellationToken ct,JsonNode? previous=null){
  if(RelationalStore.Handles(key)&&key!="conversations"){await relational.Write(c,tx,key,previous,value,rut,ct);return;}
  await RelationalStore.Exec(c,tx,"INSERT INTO shopping_ui.documents(resource,id,owner,payload) VALUES(@resource,@id,@owner,@payload::jsonb) ON CONFLICT(resource,id) DO UPDATE SET payload=EXCLUDED.payload,updated_at=now()",ct,("resource",key),("id",Key(key,rut)),("owner",Owner(key,rut)),("payload",value?.ToJsonString()??"null"));
 }
 public async Task<long> Revision(NpgsqlConnection c,NpgsqlTransaction? tx,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT revision FROM shopping_ui.state_version WHERE id=1",c,tx);return (long)(await cmd.ExecuteScalarAsync(ct))!;}
 public Task Lock(NpgsqlConnection c,NpgsqlTransaction tx,CancellationToken ct)=>RelationalStore.Exec(c,tx,"SELECT pg_advisory_xact_lock(7281156)",ct);
 public Task Bump(NpgsqlConnection c,NpgsqlTransaction tx,CancellationToken ct)=>RelationalStore.Exec(c,tx,"UPDATE shopping_ui.state_version SET revision=revision+1 WHERE id=1",ct);
 public object Snapshot(Dictionary<string,JsonNode?> data,long revision,ClaimsPrincipal user){var result=new Dictionary<string,JsonNode?>();var rut=Rut(user);foreach(var (id,value)in data){var prefix=id.StartsWith("global:")?"global:":rut+":";if(!id.StartsWith(prefix))continue;var key=id[prefix.Length..];if(rut=="guest"&&!key.StartsWith("reviews:")&&!key.StartsWith("questions:")&&!new[]{"catalog","categories","geography","zones"}.Contains(key))continue;result[key]=IsShared(key)&&value is JsonArray rows?new JsonArray(rows.Where(row=>Visible(key,row,user)).Select(row=>row?.DeepClone()).ToArray()):value?.DeepClone();}
  foreach(var key in new[]{"catalog","orders","quotes","returns","users","companies","cart","wishlist","messages","conversations","zones"})result.TryAdd(key,new JsonArray());if(rut!="guest")result.TryAdd("addresses:"+rut,new JsonArray());return new{collections=result,revision,isAuthenticated=user.Identity?.IsAuthenticated==true,source="public",dataMode="relational"};}
 public async Task<object> Read(ClaimsPrincipal user,CancellationToken ct){await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);return Snapshot(await Load(c,tx,ct),await Revision(c,tx,ct),user);}
 public async Task<object> Commit(Dictionary<string,JsonNode?> changes,long expected,ClaimsPrincipal user,CancellationToken ct,bool delta=false,Dictionary<string,string[]>? deletedIds=null){if(changes.Count is <1 or >20)throw new ArgumentException("Transacción vacía o demasiado grande.");await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await Lock(c,tx,ct);if(await Revision(c,tx,ct)!=expected)throw new StateConflictException();var data=await Load(c,tx,ct);var rut=Rut(user);
  foreach(var (key,original)in changes){Allowed(key,rut);if(key=="geography")throw new ForbiddenException();RejectSecrets(original);var value=original?.DeepClone();var previous=Get(data,key,rut);
   if(delta&&IsShared(key)&&value is JsonArray changed){var removed=deletedIds?.GetValueOrDefault(key,[])??[];if(removed.Any(id=>Rows(previous).Any(row=>Id(row)==id&&!Visible(key,row,user))))throw new ForbiddenException();value=new JsonArray(Rows(previous).Where(row=>Visible(key,row,user)&&!removed.Contains(Id(row))&&!changed.Any(n=>Id(n)==Id(row))).Select(row=>row?.DeepClone()).Concat(changed.Select(row=>row?.DeepClone())).ToArray());}
   if(key=="categories"&&!Admin(user)||key=="users"&&!Admin(user))throw new ForbiddenException();
   if(key=="zones"||key=="shippingMethod"){if(!Seller(user))throw new ForbiddenException();}
   if(key.StartsWith("profile:")){if(value is not JsonObject profile)throw new ArgumentException("Perfil inválido.");await accounts.UpdateProfile(c,tx,rut,profile,ct);}
   if(IsShared(key)&&key!="categories"&&value is not JsonArray)throw new ArgumentException("Se requiere una lista.");
   if(value is JsonArray rows&&IsShared(key)){
    if(rows.Count>50000||rows.Any(row=>row is not JsonObject||Id(row)=="")||rows.Select(Id).Distinct().Count()!=rows.Count)throw new ArgumentException("Registros o identificadores inválidos.");
    var old=Rows(previous);var oldMap=old.ToDictionary(Id);foreach(var row in rows){var before=oldMap.GetValueOrDefault(Id(row));if(before!=null&&!Visible(key,before,user))throw new ForbiddenException();if(JsonNode.DeepEquals(before,row))continue;
     if(key=="zones"){if(before!=null&&!Admin(user)&&Text(before,"ownerRut")!=rut)throw new ForbiddenException();row!["ownerRut"]=before?["ownerRut"]?.DeepClone()??JsonValue.Create(rut);if(before!=null&&!Admin(user)&&List(data,"catalog").Any(other=>Text(other,"dbId")==Text(before,"dbId")&&Text(other,"tipo")==Text(before,"tipo")&&Text(other,"ownerRut")!=rut)&&new[]{"nombre","categoria","descripcion","material","marca","peso","dimensiones","edad"}.Any(field=>!JsonNode.DeepEquals(before[field],row?[field])))throw new ArgumentException("Los atributos compartidos del artículo requieren administración; puedes ajustar tu stock, precio y ofertas.");if(Number(row,"rate")<0||Number(row,"rate")%1!=0)throw new ArgumentException("Tarifa inválida.");}
     if(key=="users"&&Text(row,"rut").Replace(".","")==rut&&Text(row,"status")=="Inactivo")throw new ArgumentException("No puedes desactivar tu propia cuenta.");
     if(key=="catalog"){
      foreach(var variant in Rows(row?["variantes"]))if(Number(variant,"stock")<0||Number(variant,"stock")%1!=0||Number(variant,"price")<=0)throw new ArgumentException("Stock o precio de variante inválido.");
      if(before!=null&&!Admin(user)&&List(data,"catalog").Any(other=>Text(other,"dbId")==Text(before,"dbId")&&Text(other,"tipo")==Text(before,"tipo")&&Text(other,"ownerRut")!=rut)){
       foreach(var variant in Rows(row?["variantes"])){var oldVariant=Rows(before["variantes"]).FirstOrDefault(v=>Text(v,"sku")==Text(variant,"sku"));if(oldVariant!=null&&new[]{"color","size"}.Any(k=>!JsonNode.DeepEquals(variant?[k],oldVariant[k])))throw new ArgumentException("Los atributos compartidos de una variante requieren administración.");}
      }
      if(!Seller(user)||before!=null&&!Admin(user)&&Text(before,"ownerRut")!=rut)throw new ForbiddenException();if(Text(row,"nombre").Trim().Length<3||(Number(row,"precio")<=0&&Text(row,"estado")!="Borrador")||Number(row,"stock")<0)throw new ArgumentException("Nombre, precio o stock inválidos.");row!["ownerRut"]=before?["ownerRut"]?.DeepClone()??JsonValue.Create(rut);if(before!=null&&!Admin(user)&&List(data,"catalog").Any(other=>Text(other,"dbId")==Text(before,"dbId")&&Text(other,"tipo")==Text(before,"tipo")&&Text(other,"ownerRut")!=rut)&&new[]{"nombre","categoria","descripcion","material","marca","peso","dimensiones","edad"}.Any(field=>!JsonNode.DeepEquals(before[field],row?[field])))throw new ArgumentException("Los atributos compartidos del artículo requieren administración; puedes ajustar tu stock, precio y ofertas.");}
     if(key=="companies"){var owner=AccountService.Rut(Text(row?["owner"],"run"));if(!Admin(user)&&(!Seller(user)||owner!=rut||before!=null&&Text(before,"ownerRut")!=rut))throw new ForbiddenException();}
     if(key=="orders"){if(before==null)throw new ArgumentException("Usa checkout para crear compras.");if(!Admin(user)&&(!Seller(user)||Text(before,"sellerRut")!=rut))throw new ForbiddenException();var canonical=before.DeepClone();canonical["status"]=Text(row,"status");canonical["dispatch"]=row?["dispatch"]?.DeepClone();row!.AsObject().Clear();foreach(var pair in canonical.AsObject())row[pair.Key]=pair.Value?.DeepClone();}
     if(key=="quotes"){if(before==null){var items=Rows(row?["items"]);if(items.Count==0)throw new ArgumentException("Cotización vacía.");var owners=new HashSet<string>();foreach(var item in items){var product=List(data,"catalog").FirstOrDefault(p=>Id(p)==Id(item))??throw new ArgumentException("Artículo inexistente.");if(Number(item,"qty")<1||Number(item,"qty")%1!=0)throw new ArgumentException("Cantidad inválida.");item!["dbId"]=product["dbId"]!.DeepClone();item["type"]=Text(product,"tipo");item["tipo"]=Text(product,"tipo");owners.Add(Text(product,"ownerRut"));}if(owners.Count!=1)throw new ArgumentException("Selecciona un solo vendedor.");row!["sellerRut"]=owners.Single();row["customerRut"]=rut;}else{var status=Text(row,"status");if(status=="Aceptada por el cliente"){if(Text(before,"customerRut")!=rut&&!Admin(user))throw new ForbiddenException();if(DateTime.Today>DateTime.Parse(Text(before,"createdAt")).Date.AddDays(15))throw new ArgumentException("La cotización venció.");}else if(status=="Respondida"){if(!Admin(user)&&(!Seller(user)||Text(before,"sellerRut")!=rut))throw new ForbiddenException();}else throw new ArgumentException("Transición de cotización inválida.");var canonical=before.DeepClone();canonical["status"]=status;row!.AsObject().Clear();foreach(var pair in canonical.AsObject())row[pair.Key]=pair.Value?.DeepClone();}}
     if(key=="returns"){if(before==null){var order=List(data,"orders").FirstOrDefault(o=>Id(o)==Text(row,"orderId"))??throw new ArgumentException("Pedido inexistente.");if(Text(order,"customerRut")!=rut||Text(order,"status") is not ("Entregado" or "Recibido"))throw new ForbiddenException();var line=Rows(order["products"]).FirstOrDefault(p=>Id(p)==Text(row,"productId")&&Text(p,"sku")==Text(row,"sku"))??throw new ArgumentException("Artículo inexistente.");if(Number(row,"qty")<1||Number(row,"qty")%1!=0||Number(row,"qty")>Number(line,"qty"))throw new ArgumentException("Cantidad inválida.");row!["customerRut"]=rut;row["sellerRut"]=Text(order,"sellerRut");row["status"]="Solicitada";}else{if(!Admin(user)&&(!Seller(user)||Text(before,"sellerRut")!=rut))throw new ForbiddenException();var status=Text(row,"status");if(status is not ("Solicitada" or "Aprobada" or "Rechazada"))throw new ArgumentException("Estado de devolución inválido.");var canonical=before.DeepClone();canonical["status"]=status;row!.AsObject().Clear();foreach(var pair in canonical.AsObject())row[pair.Key]=pair.Value?.DeepClone();}}
     if(key=="messages"){if(before!=null)throw new ArgumentException("Los mensajes enviados conservan su historial.");var thread=List(data,"conversations").FirstOrDefault(t=>Id(t)==Text(row,"conversationId"))??throw new ArgumentException("Selecciona una conversación.");if(!Visible(key,thread,user)||(rut!=Text(thread,"customerRut")&&rut!=Text(thread,"sellerRut"))||Text(row,"text").Trim().Length is <1 or >2000)throw new ForbiddenException();row!["customerRut"]=Text(thread,"customerRut");row["sellerRut"]=Text(thread,"sellerRut");}
     if(key=="conversations"){if(before==null){var product=List(data,"catalog").FirstOrDefault(p=>Id(p)==Text(row,"productId"))??throw new ArgumentException("La conversación debe indicar un artículo real.");row!["customerRut"]=rut;row["sellerRut"]=Text(product,"ownerRut");row["customerName"]=user.Identity?.Name;row["name"]=Text(product,"vendedor");}else{row!["customerRut"]=Text(before,"customerRut");row["sellerRut"]=Text(before,"sellerRut");row["productId"]=before["productId"]?.DeepClone();row["customerName"]=before["customerName"]?.DeepClone();}}
     if(key.StartsWith("questions:")||key.StartsWith("reviews:")){var product=List(data,"catalog").FirstOrDefault(p=>Id(p)==key[(key.IndexOf(':')+1)..])??throw new ArgumentException("Artículo inexistente.");if(before!=null){if(!key.StartsWith("questions:")||!Admin(user)&&Text(product,"ownerRut")!=rut)throw new ForbiddenException();var answer=Text(row,"answer").Trim();if(answer.Length is <3 or >2000)throw new ArgumentException("Respuesta inválida.");var canonical=before.DeepClone();canonical["answer"]=answer;row!.AsObject().Clear();foreach(var pair in canonical.AsObject())row[pair.Key]=pair.Value?.DeepClone();}else{row!["customerRut"]=rut;if(key.StartsWith("questions:")&&Text(row,"question").Trim().Length is <5 or >1000)throw new ArgumentException("Pregunta inválida.");}}
    }
    var presentIds=rows.Select(Id).ToHashSet();var deleted=old.Where(x=>Visible(key,x,user)&&!presentIds.Contains(Id(x))).ToArray();if(deleted.Length>0&&!new[]{"catalog","users","companies","zones"}.Contains(key))throw new ArgumentException("Este recurso conserva su historial.");if(deleted.Any(x=>!Admin(user)&&(key!="catalog"&&key!="zones"||!Seller(user)||Text(x,"ownerRut")!=rut)))throw new ForbiddenException();
    value=new JsonArray(old.Where(x=>!Visible(key,x,user)).Select(x=>x?.DeepClone()).Concat(rows.Select(x=>x?.DeepClone())).ToArray());
   }
   if(key.StartsWith("addresses:")&&Rows(previous).Any(old=>!Rows(value).Any(n=>Id(n)==Id(old))))throw new ArgumentException("El perfil conserva sus direcciones; puedes editarlas o agregar otra.");
   await Save(c,tx,key,rut,value,ct,previous);data[Key(key,rut)]=value;
  }
  await Bump(c,tx,ct);var version=await Revision(c,tx,ct);var fresh=await Load(c,tx,ct);await tx.CommitAsync(ct);return Snapshot(fresh,version,user);
 }
 public async Task<object> Maintain(ClaimsPrincipal user,CancellationToken ct){await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await Lock(c,tx,ct);var changes=await RelationalStore.Query(c,tx,"SELECT to_jsonb(t)::text FROM public.fn_mantenimiento() t",ct);if(changes.Any(row=>Number(row,"cotizaciones_actualizadas")+Number(row,"cotizaciones_eliminadas")+Number(row,"productos_actualizados")>0))await Bump(c,tx,ct);if(user.Identity?.IsAuthenticated!=true){await tx.CommitAsync(ct);return new{status="ok"};}var data=await Load(c,tx,ct);var version=await Revision(c,tx,ct);await tx.CommitAsync(ct);return Snapshot(data,version,user);}
 static void Allowed(string key,string rut){if(Shared.Contains(key)||Private.Contains(key)||new[]{"profile:","addresses:","preferences:"}.Any(p=>key==p+rut)||System.Text.RegularExpressions.Regex.IsMatch(key,@"^(reviews|questions):[\w-]+$"))return;throw new ArgumentException("Recurso desconocido o ajeno.");}
 static void RejectSecrets(JsonNode? value){if(value is JsonObject obj)foreach(var pair in obj){if(System.Text.RegularExpressions.Regex.IsMatch(pair.Key,"password|passwd|contrase|token|secret|salt",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new ArgumentException("No se permiten credenciales en documentos.");RejectSecrets(pair.Value);}else if(value is JsonArray list)foreach(var row in list)RejectSecrets(row);}
}
public sealed class StateConflictException:Exception;
public sealed class ForbiddenException:Exception;
